# ============================================================
# CROSS-PLATFORM MIDI PLAYER
# ============================================================
# Uses only operating-system/system tools:
#   Windows: Windows MCI / winmm
#   macOS:   "open" the MIDI file with the default MIDI player
#   Linux:   "aplaymidi" + the first available ALSA MIDI port
#
# Keep the MIDI file here:
#     assets/nyan.mid
# ============================================================

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
MIDI_FILE = os.path.join(BASE_DIR, "assets", "nyan.mid")


class MidiPlayer:
    def __init__(self, filename):
        self.filename = filename
        self.system = platform.system()
        self.process = None
        self.playing = False

    def play(self):
        if not os.path.isfile(self.filename):
            print("[MIDI] File not found:", self.filename)
            print("[MIDI] Animation will continue without music.")
            return

        try:
            if self.system == "Windows":
                self.play_windows()

            elif self.system == "Darwin":
                self.play_macos()

            elif self.system == "Linux":
                self.play_linux()

            else:
                print("[MIDI] Unsupported operating system:", self.system)

        except Exception as error:
            print("[MIDI] Playback failed:", error)
            print("[MIDI] Animation will continue without music.")

    def play_windows(self):
        winmm = ctypes.windll.winmm

        # Close a previous alias if one somehow remains.
        try:
            winmm.mciSendStringW(
                "close nyan_midi",
                None,
                0,
                None
            )
        except Exception:
            pass

        command = (
            f'open "{self.filename}" '
            f'type sequencer alias nyan_midi'
        )

        result = winmm.mciSendStringW(
            command,
            None,
            0,
            None
        )

        if result != 0:
            print("[MIDI] Could not open MIDI on Windows.")
            return

        result = winmm.mciSendStringW(
            "play nyan_midi",
            None,
            0,
            None
        )

        if result != 0:
            print("[MIDI] Could not play MIDI on Windows.")
            winmm.mciSendStringW(
                "close nyan_midi",
                None,
                0,
                None
            )
            return

        self.playing = True
        print("[MIDI] Windows MIDI playback started.")

    def play_macos(self):
        # macOS opens the MIDI with the system-associated application.
        self.process = subprocess.Popen(
            ["open", self.filename],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL
        )

        self.playing = True
        print("[MIDI] MIDI opened on macOS.")

    def play_linux(self):
        aplaymidi = shutil.which("aplaymidi")

        if not aplaymidi:
            print("[MIDI] aplaymidi is not installed.")
            print("[MIDI] Animation will continue without music.")
            return

        result = subprocess.run(
            [aplaymidi, "-l"],
            capture_output=True,
            text=True
        )

        port = self.find_port(result.stdout)

        if not port:
            print("[MIDI] No ALSA MIDI output port was found.")
            print("[MIDI] Animation will continue without music.")
            return

        self.process = subprocess.Popen(
            [
                aplaymidi,
                "-p",
                port,
                self.filename
            ],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL
        )

        self.playing = True
        print("[MIDI] Linux MIDI playback started on", port)

    @staticmethod
    def find_port(output):
        for line in output.splitlines():
            line = line.strip()

            if not line:
                continue

            parts = line.split()

            if parts and ":" in parts[0]:
                return parts[0]

        return None

    def stop(self):
        try:
            if self.system == "Windows" and self.playing:
                winmm = ctypes.windll.winmm

                winmm.mciSendStringW(
                    "stop nyan_midi",
                    None,
                    0,
                    None
                )

                winmm.mciSendStringW(
                    "close nyan_midi",
                    None,
                    0,
                    None
                )

            elif self.process:
                self.process.terminate()
                self.process = None

        except Exception:
            pass

        self.playing = False


root = tk.Tk()
root.title("Nyan Cat")
print("[NYAN] Cross-platform MIDI player enabled.")
root.resizable(False, False)

canvas = tk.Canvas(
    root,
    width=DISPLAY_SIZE,
    height=DISPLAY_SIZE,
    bg=SPACE,
    highlightthickness=0,
    bd=0
)
canvas.pack()


# Draw the clean static stars once.
for x, y in STARS:
    canvas.create_rectangle(
        x * SCALE,
        y * SCALE,
        (x + 1) * SCALE,
        (y + 1) * SCALE,
        fill="#ffffff",
        outline=""
    )


def make_frame(rows):
    image = tk.PhotoImage(
        width=LOGICAL_SIZE,
        height=LOGICAL_SIZE
    )

    for y, row in enumerate(rows):
        colors = []

        for char in row:
            if char == ".":
                colors.append(SPACE)
            else:
                colors.append(COLORS[char])

        image.put(
            "{" + " ".join(colors) + "}",
            to=(0, y)
        )

    # Nearest-neighbour pixel scaling: every logical pixel becomes
    # exactly a 3x3 square.
    return image.zoom(SCALE, SCALE)


# Pre-build all frames once for smooth animation.
FRAME_IMAGES = [
    make_frame(frame)
    for frame in FRAMES
]

sprite = canvas.create_image(
    0,
    0,
    anchor="nw",
    image=FRAME_IMAGES[0]
)

frame_number = 0


def animate():
    global frame_number

    frame_number = (frame_number + 1) % FRAME_COUNT

    canvas.itemconfig(
        sprite,
        image=FRAME_IMAGES[frame_number]
    )

    root.after(
        FRAME_DELAY_MS,
        animate
    )


root.after(FRAME_DELAY_MS, animate)

# Start the MIDI at the same time as the animation.
midi = MidiPlayer(MIDI_FILE)
midi.play()


def close():
    midi.stop()
    root.destroy()


root.protocol(
    "WM_DELETE_WINDOW",
    close
)

root.mainloop()
